namespace Astrea;

public class MultipleActionCustomDescription : CustomBattleActionDescription
{
	protected bool IsAddHighlight()
	{
		if (GameScenesUtils.IsBattleScene())
		{
			if (ReferenceSingleton<GameStateManager>.Instance.CurrentState == ReferenceSingleton<GameStateManager>.Instance.PlayerRewardState || ReferenceSingleton<GameStateManager>.Instance.CurrentState == ReferenceSingleton<GameStateManager>.Instance.MapState || ReferenceSingleton<GameStateManager>.Instance.CurrentState == ReferenceSingleton<GameStateManager>.Instance.PlayerUnlockablesState)
			{
				return false;
			}
			return true;
		}
		return false;
	}

	protected string GetHighlightedDescription(string description)
	{
		return "<b>" + description + "</b>";
	}
}
